<script setup lang="ts">
import {provideInputContext} from './inputAssistance'
import {onMounted,ref,toRaw} from 'vue'
import {useRouter} from 'vue-router'
import {api} from './api'
const router=useRouter(),topic=ref(''),audience=ref('高校本科生'),lessons=ref(6),language=ref('zh-CN'),requirements=ref(''),sourceId=ref('')
const languages:Record<string,string>={'zh-CN':'中文','en-US':'英语','ja-JP':'日语','ko-KR':'韩语','de-DE':'德语','fr-FR':'法语','ru-RU':'俄语','es-ES':'西班牙语'}
const targets=ref(['zh-CN']),pagesPerLesson=ref(5),plans=ref<any[]>([]),courses=ref<any[]>([]),plan=ref<any>(),selectedId=ref(''),batch=ref<any>(),busy=ref(false),error=ref(''),message=ref('')
async function post(path:string,body:any){return api<any>(path,{method:'POST',body:JSON.stringify(body),signal:AbortSignal.timeout(600000)})}
async function perform(fn:()=>Promise<void>){busy.value=true;error.value='';message.value='';try{await fn()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
onMounted(()=>perform(async()=>{plans.value=await api<any[]>('/v1/studio/plans');courses.value=(await api<any[]>('/v1/studio/courses')).filter(x=>['owner','editor'].includes(x.role))}))
function load(){const stored=plans.value.find(x=>x.id===selectedId.value);plan.value=stored?structuredClone(toRaw(stored)):undefined;if(plan.value){topic.value=plan.value.topic;audience.value=plan.value.audience;lessons.value=plan.value.outline.length;language.value=plan.value.language;requirements.value=plan.value.requirements||'';sourceId.value=plan.value.sourceTaskId||''}}
function generate(){void perform(async()=>{plan.value=await post('/v1/studio/plans',{topic:topic.value,audience:audience.value,lessons:lessons.value,language:language.value,requirements:requirements.value,sourceTaskId:sourceId.value||null});plans.value=await api<any[]>('/v1/studio/plans');selectedId.value=plan.value.id;message.value='课程方案已生成并保存，可逐课编辑。'})}
function save(){void perform(async()=>{plan.value=await post('/v1/studio/plans/'+plan.value.id+'/save',{revision:plan.value.revision,outline:plan.value.outline,requirements:requirements.value});plans.value=await api<any[]>('/v1/studio/plans');message.value='编辑后的课程方案已保存。'})}
function start(){const query=new URLSearchParams({topic:topic.value,audience:audience.value,mode:'topic',memoryCourseId:sourceId.value,requirements:plan.value?plan.value.outline.map((x:any)=>x.title+'：'+x.objective+'；'+x.requirements).join('\n'):requirements.value});void router.push('/create?'+query)}
function launch(){void perform(async()=>{batch.value=await post('/v1/studio/plans/'+plan.value.id+'/launch',{targetLanguages:targets.value,totalPages:pagesPerLesson.value,execute:true});message.value='系列任务已创建，各任务的处理状态可分别查看。'})}
provideInputContext(()=>({courseId:sourceId.value||undefined,language:language.value,context:{topic:topic.value,audience:audience.value,requirements:requirements.value,lessons:lessons.value,outline:plan.value?.outline}}))
</script>
<template>
 <div class="planner"><div class="heading"><div><h1>课程方案与系列制作</h1><p>结合教学要求和课程材料生成可编辑大纲，并保存到当前账号。</p></div></div><section class="panel"><label>我的方案<select v-model="selectedId" @change="load"><option value="">选择已保存方案</option><option v-for="item in plans" :key="item.id" :value="item.id">{{item.topic}} · 版本 {{item.revision}}</option></select></label><div class="form-grid"><label>课程主题<AssistedInput v-model="topic" maxlength="300" assist-label="课程主题" assist-purpose="topic"/></label><label>教学对象<AssistedInput v-model="audience" maxlength="300" assist-label="教学对象" assist-purpose="audience"/></label><label>课时数<input v-model.number="lessons" type="number" min="1" max="12"></label><label>方案语种<select v-model="language"><option v-for="(name,code) in languages" :key="code" :value="code">{{name}}</option></select></label></div><label>参考已有课程材料与记忆<select v-model="sourceId"><option value="">不选择已有课程</option><option v-for="item in courses" :key="item.id" :value="item.id">{{item.name}}</option></select></label><label>课程要求<AssistedTextarea v-model="requirements" rows="4" maxlength="3000" placeholder="教学重点、已有基础、必须保留的概念、例子和资料范围" assist-label="课程要求" assist-purpose="requirements"/></label><button :disabled="busy||!topic.trim()" @click="generate">生成并保存课程方案</button><button :disabled="busy||!topic.trim()" @click="start">进入单门课程创建</button></section><p v-if="error" class="notice error" role="alert">{{error}}</p><p v-if="message" class="notice" role="status">{{message}}</p><section v-if="plan" class="panel"><h2>可编辑课程大纲 · 版本 {{plan.revision}}</h2><article v-for="(item,index) in plan.outline" :key="index"><h3>第 {{index+1}} 课</h3><label>课时标题<AssistedInput v-model="item.title" maxlength="200" assist-label="课时标题" assist-purpose="topic"/></label><label>教学目标<AssistedTextarea v-model="item.objective" rows="2" assist-label="课时教学目标" assist-purpose="requirements"/></label><label>教学活动<AssistedTextarea v-model="item.activity" rows="2" assist-label="教学活动" assist-purpose="requirements"/></label><label>内容要求<AssistedTextarea v-model="item.requirements" rows="2" assist-label="课时内容要求" assist-purpose="requirements"/></label><label>期望时长（分钟）<input v-model.number="item.minutes" type="number" min="1" max="180"></label></article><button :disabled="busy" @click="save">保存大纲修改</button><p>保存当前大纲和总体要求。修改主题、对象、课时数或参考课程后，请重新生成方案。</p><h3>批量制作整套课程</h3><label>每门课程的课件页数<input v-model.number="pagesPerLesson" type="number" min="1" max="30"></label><p>批量制作采用已保存的大纲，请先保存编辑内容。</p><div class="targets"><label v-for="(name,code) in languages" :key="code"><input v-model="targets" type="checkbox" :value="code">{{name}}</label></div><button :disabled="busy||!targets.length" @click="launch">创建系列课程并开始生成</button><div v-if="batch"><p>已创建 {{batch.taskIds.length}} 门课程。</p><p v-for="id in batch.taskIds" :key="id"><a :href="'#/task?id='+id">查看课程 {{id}}</a></p><p v-for="row in batch.errors" :key="row.taskId">{{row.message}}</p></div></section></div>
</template>
<style scoped>.planner{max-width:1150px;margin:auto;color:#234a35}.panel{padding:22px;margin:18px 0;background:#fff;border:1px solid #dce7df;border-radius:10px}.planner label{display:block;font-size:13px;margin:12px 0}.planner input:not([type=checkbox]),.planner textarea,.planner select{display:block;box-sizing:border-box;width:100%;padding:10px;margin-top:6px;font:inherit;font-size:16px;border:1px solid #cbd9ce;border-radius:6px;color:#234a35;background:#fff}.form-grid{display:grid;grid-template-columns:2fr 2fr 1fr 1fr;gap:14px}.planner button,.planner a{padding:10px 14px;margin:4px 8px 4px 0;border:1px solid #cbdccf;border-radius:6px;background:#eef5ef;color:#24543d;cursor:pointer;font:inherit;font-size:13px}.planner button:disabled{opacity:.5}.planner article{padding:10px 0;border-bottom:1px solid #e4ece6}.targets{display:flex;gap:12px;flex-wrap:wrap}.notice{padding:12px;background:#edf5ef;border-radius:8px;font-size:13px}.error{color:#a1412b;background:#fff0ec}@media(max-width:760px){.form-grid{grid-template-columns:1fr 1fr}.panel{padding:14px}}</style>
